   } elseif($action==='resolve_alert'){$result=sk1000_resolve_alert((int)($_POST['id']??0),$uid);$flash='Alert resolved.';
   } elseif($action==='cleanup'){$result=sk1000_cleanup($uid);$flash='Telemetry retention cleanup completed.';
   } elseif($action==='scan_alerts'){$result=['generated'=>sk1000_generate_alerts()];$flash='Security/performance alert scan completed.';}
 }
}catch(Throwable $e){$error=$e->getMessage();}
